package com.fakrudeenmart.servlet;
import com.fakrudeenmart.model.UserRole; import com.fakrudeenmart.service.AdminService;
import javax.servlet.ServletException; import javax.servlet.http.*; import java.io.IOException;
public class AdminUserListServlet extends HttpServlet { private AdminService service; public void init(){service=new AdminService();} protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{String path=req.getRequestURI();UserRole role=path.contains("/buyers")?UserRole.BUYER:path.contains("/sellers")?UserRole.SELLER:AdminServletSupport.role(req.getParameter("role"));req.setAttribute("users",service.getUsers(AdminServletSupport.adminId(req),req.getParameter("search"),role,AdminServletSupport.userStatus(req.getParameter("status"))));req.setAttribute("roleFilter",role);req.setAttribute("statusFilter",req.getParameter("status"));req.setAttribute("search",req.getParameter("search"));req.setAttribute("listType",role==UserRole.BUYER?"buyers":role==UserRole.SELLER?"sellers":"users");req.getRequestDispatcher("/WEB-INF/views/admin/users.jsp").forward(req,resp);} }
